import boto3

from storage_client import get_s3_client


def list_objects_with_prefix(prefix, bucket, config=None):
    config = config or {}
    client = get_s3_client(config)
    response = client.list_objects_v2(Bucket=bucket, Prefix=prefix)
    return response.get('Contents', [])

import boto3


def get_s3_client(config):
    return boto3.client('s3', region_name=config.get('region', 'us-west-2'))

class Payload:
    def __init__(self, object_name, data, content_type='application/octet-stream'):
        self.object_name = object_name
        self.data = data
        self.content_type = content_type


class Config:
    def __init__(self, region=None, bucket=None):
        self.region = region
        self.bucket = bucket
